import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log


def test_parse_skips_blank_and_comment_lines_and_strips_fields():
    lines = ["", " \t", "  # header", " a , 3 , 1 ", " b , 4 , 0", " c , 5 , "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 3, "converted": True},
        {"id": "b", "day": 4, "converted": False},
        {"id": "c", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1"])
def test_parse_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# header", "a,1,1", "  ", bad_line])


def test_dedupe_keeps_last_record_for_each_id_then_sorts():
    events = parse_session_log(["z,9,1", "b,4,1", "a,4,1", "z,2,0"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_daily_counts_include_gaps_and_ignore_outside_days():
    events = parse_session_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1", "f,6,1"])
    assert daily_conversion_counts(events, 2, 5) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 5, 2) == []
